changeSet.sql:
DO $do$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'eleicoes_app') THEN
        GRANT USAGE ON SCHEMA public TO eleicoes_app;
        GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO eleicoes_app;
        GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO eleicoes_app;
        ALTER DEFAULT PRIVILEGES FOR ROLE CURRENT_USER IN SCHEMA public
            GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO eleicoes_app;
        ALTER DEFAULT PRIVILEGES FOR ROLE CURRENT_USER IN SCHEMA public
            GRANT USAGE, SELECT ON SEQUENCES TO eleicoes_app;
    END IF;
END
$do$;
